        { q: "typeof [] is\u2026", o: ['"array"', '"object"', '"list"', '"undefined"'], a: 1, e: "Arrays are objects. Use Array.isArray()." },
        { q: "Which is NOT a primitive?", o: ["string", "boolean", "object", "symbol"], a: 2, e: "object is a reference type." }
