      starter: { html: `<table id="t"></table>
<div id="summary"></div>`, css: ``, js: `const subjects = ["Web Dev", "Maths", "Python", "Physics", "English"];` },
      solution: { html: `<h2>Semester Result Calculator</h2>
<table>
  <thead><tr><th>Subject</th><th>Credits</th><th>Marks /100</th><th>Grade</th></tr></thead>
  <tbody id="rows"></tbody>
</table>
<div id="summary" class="summary" role="status"></div>`, css: `body { font-family: system-ui; color: #30343B; }
table { border-collapse: collapse; width: 100%; max-width: 520px; }
th, td { border: 2px solid #30343B; padding: 6px 10px; text-align: left; }
th { background: #FFD45C; }
input { width: 70px; padding: 4px; border: 2px solid #30343B; border-radius: 6px; }
tr.fail { background: #FDE3EC; }
.summary { margin-top: 12px; padding: 12px; border: 2px solid #30343B; border-radius: 12px; max-width: 496px; background: #E2F4DE; }
.summary.bad { background: #FDE3EC; }`, js: `const subjects = [
  { name: "Web Technologies", credits: 4 },
  { name: "Mathematics I", credits: 4 },
  { name: "Python Programming", credits: 3 },
  { name: "Physics", credits: 3 },
  { name: "Communication Skills", credits: 2 },
];
const rows = document.getElementById("rows");
subjects.forEach((s, i) => {
  const tr = document.createElement("tr");
  tr.innerHTML = "<td></td><td>" + s.credits + '</td><td><input type="number" min="0" max="100" value="' + (60 + i * 7) + '" aria-label="Marks"></td><td class="g"></td>';
  tr.firstChild.textContent = s.name;
  rows.append(tr);
});

function gradeOf(m) {
  if (m >= 90) return ["O", 10];
  if (m >= 80) return ["A+", 9];
  if (m >= 70) return ["A", 8];
  if (m >= 60) return ["B+", 7];
  if (m >= 50) return ["B", 6];
  if (m >= 40) return ["C", 5];
  return ["F", 0];
}

function calculate() {
  const inputs = [...rows.querySelectorAll("input")];
  const marks = inputs.map((inp) => Math.min(100, Math.max(0, Number(inp.value) || 0)));
  let credits = 0, points = 0;
  marks.forEach((m, i) => {
    const [g, gp] = gradeOf(m);
    const tr = rows.children[i];
    tr.querySelector(".g").textContent = g;
    tr.classList.toggle("fail", g === "F");
    credits += subjects[i].credits;
    points += gp * subjects[i].credits;
  });
  const total = marks.reduce((a, b) => a + b, 0);
  const pct = (total / (marks.length * 100)) * 100;
  const sgpa = points / credits;
  const failed = marks.filter((m) => m < 40).length;
  const box = document.getElementById("summary");
  box.className = "summary" + (failed ? " bad" : "");
  box.textContent = "Total: " + total + "/" + marks.length * 100 + " \xB7 " + pct.toFixed(2) + "% \xB7 SGPA: " + sgpa.toFixed(2) + (failed ? " \xB7 Back in " + failed + " subject(s)" : " \xB7 PASS");
}
rows.addEventListener("input", calculate);
calculate();` },
